-- =============================================================================
-- 034 : RCP BDPM condensé → matrice_medicaments (Cardio DEUST 2A)
-- Généré par sql/ops/cardio_rcp_matrice_gen.mjs — NE PAS éditer à la main.
-- Matrice / référentiel uniquement ; publications DEUST = source cours (035).
-- EI : fréquents ou rares graves. Idempotent (jp_fill sans doublon).
-- =============================================================================

CREATE OR REPLACE FUNCTION pg_temp.jp_ent(p_table text, p_valeur text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_id uuid; v_norm text := jeupharma.normaliser_valeur(p_valeur);
BEGIN
  EXECUTE format('SELECT id FROM jeupharma.%I WHERE valeur_norm = $1 AND actif LIMIT 1', p_table) INTO v_id USING v_norm;
  IF v_id IS NULL THEN
    EXECUTE format('INSERT INTO jeupharma.%I (valeur, valeur_norm) VALUES ($1, $2) RETURNING id', p_table) INTO v_id USING p_valeur, v_norm;
  END IF;
  RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_fill(p_matrice uuid, p_champ text, p_vals text[])
RETURNS void LANGUAGE plpgsql AS $$
DECLARE v_tbl text; v_jt text; v_fk text; v_id uuid; i int;
BEGIN
  SELECT t.ent, t.jt, t.fk INTO v_tbl, v_jt, v_fk FROM (VALUES
    ('secteurs','secteurs_therapeutiques','matrice_secteurs_therapeutiques','secteur_therapeutique_id'),
    ('ct','classes_therapeutiques','matrice_classes_therapeutiques','classe_therapeutique_id'),
    ('cp','classes_pharmacologiques','matrice_classes_pharmacologiques','classe_pharmacologique_id'),
    ('ind','indications','matrice_indications','indication_id'),
    ('ci','contre_indications','matrice_contre_indications','contre_indication_id'),
    ('ei','effets_indesirables','matrice_effets_indesirables','effet_indesirable_id'),
    ('pre','precautions_emploi','matrice_precautions_emploi','precaution_emploi_id'),
    ('inter','interactions','matrice_interactions','interaction_id'),
    ('surv','surveillances','matrice_surveillances','surveillance_id'),
    ('noms','noms_commerciaux','matrice_noms_commerciaux','nom_commercial_id')
  ) AS t(champ, ent, jt, fk) WHERE t.champ = p_champ;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'champ inconnu %', p_champ; END IF;
  IF p_vals IS NULL THEN RETURN; END IF;
  FOR i IN 1 .. coalesce(array_length(p_vals, 1), 0) LOOP
    v_id := pg_temp.jp_ent(v_tbl, p_vals[i]);
    EXECUTE format(
      'INSERT INTO jeupharma.%I (matrice_id, %I, ordre) SELECT $1, $2, $3 WHERE NOT EXISTS (SELECT 1 FROM jeupharma.%I WHERE matrice_id = $1 AND %I = $2)',
      v_jt, v_fk, v_jt, v_fk) USING p_matrice, v_id, i - 1;
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_matrice_by_norm(p_norm text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_m uuid;
BEGIN
  SELECT m.id INTO v_m FROM jeupharma.matrice_medicaments m
  JOIN jeupharma.dcis d ON d.id = m.dci_id
  WHERE d.valeur_norm = jeupharma.normaliser_valeur(p_norm) AND m.statut = 'publie' LIMIT 1;
  IF v_m IS NULL THEN RAISE EXCEPTION 'fiche publie introuvable norm=%', p_norm; END IF;
  RETURN v_m;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_detail_set(p_matrice uuid, p_valeur text)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  UPDATE jeupharma.matrice_medicaments
  SET detail_pharmacologie_id = pg_temp.jp_ent('details_pharmacologie', p_valeur), updated_at = now()
  WHERE id = p_matrice;
END $$;

DO $mig$
DECLARE
  m uuid;
BEGIN
  -- nicardipine (CIS 67962026)
  m := pg_temp.jp_matrice_by_norm('nicardipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : INHIBITEURS CALCIQUES SELECTIFS A EFFETS VASCULAIRES');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['La nicardipine par voie intraveineuse est indiquée dans l’urgence hypertensive menaçant le pronostic vital, en particulier en cas de :', 'Hypertension artérielle maligne/Encéphalopathie hypertensive,', 'Dissection aortique, quand le traitement par des bêta-bloquants à courte durée d’action n’est pas approprié, ou en association avec un bêta-bloquant quand le blocage des récepteurs bêta seul n’est pas efficace,', 'Pré-éclampsie sévère, quand d’autres agents antihypertenseurs administrés par voie intraveineuse ne sont pas recommandés ou sont contre-indiqués.', 'La nicardipine est également indiquée dans le traitement de l’hypertension post-opératoire.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1,', 'Sténose aortique sévère,', 'Hypertension compensatoire, en cas de shunt artérioveineux ou de coarctation de l’aorte,', 'Angor instable,', 'Dans les 8 jours après un infarctus du myocarde.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde', 'Il est recommandé d’administrer la nicardipine avec précaution pour éviter une chute excessive de la pression artérielle.', 'En effet, des réductions pharmacologiques rapides de la pression artérielle peuvent entraîner une hypotension systémique et une tachycardie réflexe.', 'Si l’un de ces deux effets apparaît sous nicardipine, il peut être nécessaire de diminuer la dose de moitié ou d’arrêter la perfusion.', 'Insuffisance cardiaque', 'Maladie cardiovasculaire ischémique', 'La nicardipine est contre-indiquée dans l’angor instable et dans les suites immédiates d’un infarctus du myocarde (voir rubrique 4.3).', 'La nicardipine doit être utilisée avec précautions chez les patients pour lesquels une ischémie coronarienne est suspectée.', 'Occasionnellement, des patients ont développé une augmentation de la fréquence, de la durée ou de la sévérité de l’angor à l’initiation ou lors d’augmentation des doses de nicardipine, ou au cours du traitement.', 'Grossesse', 'En raison du risque d’hypotension maternelle sévère et d’hypoxie fœtale potentiellement fatale, la diminution de la pression artérielle doit être progressive et toujours étroitement surveillée.', 'En raison du risque potentiel d’œdème pulmonaire ou d’une diminution excessive de la pression artérielle, des précautions doivent être prises en cas d’administration concomitante de sulfate de magnésium.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations déconseillées', 'Dantrolène', 'Avec le dantrolène administré par perfusion :', 'Dans des études chez l’animal, des cas de fibrillations ventriculaires mortelles sont constamment observées lors de l’administration de vérapamil et de dantrolène par voie intraveineuse.', 'L’association d’un antagoniste du calcium et de dantrolène est donc potentiellement dangereuse.', 'Cependant, quelques patients ont reçu l’association nifédipine et dantrolène sans inconvénient.', 'Associations faisant l''objet de précautions d’emploi', 'Idélalisib', 'Majoration des effets indésirables de la nicardipine, à type d’hypotension orthostatique, notamment chez le sujet âgé.', 'Surveillance clinique et adaptation de la posologie de la nicardipine pendant le traitement par l’idélalisib et après son arrêt.', 'Immunosuppresseurs (ciclosporine, everolimus, sirolimus, tacrolimus, temsirolimus)', 'Augmentation des concentrations sanguines de l’immunosuppresseur, par inhibition de son métabolisme.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets les plus fréquents sont des céphalées, des vertiges, des œdèmes périphériques, des palpitations et des bouffées congestives.', 'Les catégories de fréquence sont définies selon la convention suivante : très fréquent (≥ 1/10), fréquent (≥ 1/100 à', 'Fréquence indéterminée – réaction anaphylactique']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['En raison du risque d’hypotension maternelle sévère et d’hypoxie fœtale potentiellement fatale, la diminution de la pression artérielle doit être progressive et toujours étroitement surveillée.']);

  -- nitrendipine (CIS 67688899)
  m := pg_temp.jp_matrice_by_norm('nitrendipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteurs calciques sélectifs à effets vasculaires, code ATC : C08CA08.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement de l''hypertension artérielle.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament est contre-indiqué :', 'en cas d’hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1,', 'en cas d’angor instable ou dans les 4 semaines suivant un infarctus du myocarde aigu,', 'pendant la grossesse et l’allaitement (voir rubrique 4.6),', 'en association avec la rifampicine.', 'Par conséquent, l’administration concomitante de rifampicine est contre-indiquée (voir rubrique 4.5).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mise en garde', 'Insuffisance cardiaque décompensée', 'Les patients souffrant d’une insuffisance cardiaque décompensée doivent être traités avec précaution.', 'Troubles hépatiques', 'Chez les patients présentant des troubles hépatiques sévères, les effets de la nitrendipine peuvent être renforcés et prolongés.', 'Dans ce cas, les patients doivent être étroitement surveillés par un contrôle fréquent de leur pression artérielle au cours du traitement (voir rubriques 4.2 et 5.2).', 'Comme avec d’autres substances vasoactives, un angor peut survenir de façon très rare avec la nitrendipine, en particulier au début du traitement (données issues de la notification spontanée).', 'Les données issues des études cliniques confirment que la survenue de cet angor est peu fréquente (voir rubrique 4.8).', 'Ce médicament ne doit généralement pas être utilisé :', 'en cas d’association au dantrolène (perfusion) (voir rubrique 4.5).', 'Cytochrome CYP 3A4', 'La nitrendipine est métabolisée par le cytochrome CYP3A4.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['La nitrendipine est métabolisée par le cytochrome CYP3A4, situé dans la muqueuse intestinale et le foie.', 'Les médicaments connus pour inhiber ou stimuler ce système enzymatique peuvent donc modifier le métabolisme de premier passage ou la clairance de la nitrendipine.', 'L’importance et la durée de l''interaction doivent être prises en compte lors de l''administration concomitante de la nitrendipine avec de tels médicaments.', 'Associations contre-indiquées', '+ Rifampicine', 'L’efficacité de la nitrendipine pourrait donc être diminuée en cas d’administration concomitante avec la rifampicine.', 'L’utilisation de la nitrendipine en association à la rifampicine est en conséquence contre-indiquée (voir rubrique 4.3).', 'En cas d’administration concomitante avec les inhibiteurs du cytochrome CYP3A4, il convient de surveiller la tension artérielle et d’envisager éventuellement une diminution de la dose de nitrendipine.', 'Associations déconseillées', '+ Dantrolène (administré par perfusion)', 'Chez l''animal, des cas de fibrillations ventriculaires mortelles sont constamment observés lors de l''administration de vérapamil et de dantrolène par voie IV.', 'L''association d''un antagoniste du calcium et de dantrolène est donc potentiellement dangereuse.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent (≥ 1/10),', 'Fréquent (≥ 1/100 à', 'Peu fréquent (≥ 1/1 000 à']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Dans ce cas, les patients doivent être étroitement surveillés par un contrôle fréquent de leur pression artérielle au cours du traitement (voir rubriques 4.2 et 5.2).']);

  -- isradipine (CIS 67966754)
  m := pg_temp.jp_matrice_by_norm('isradipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : INHIBITEURS DES CANAUX CALCIQUES SÉLECTIFS VASCULAIRES, code ATC : C08CA03.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement de l’hypertension artérielle.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité connue à l’isradipine, aux autres inhibiteurs des canaux calciques de la famille des dihydropyridines ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Comme avec les autres inhibiteurs des canaux calciques, ICAZ LP 2,5 mg, gélule ne doit pas être utilisé chez les patients présentant les conditions suivantes :', 'Choc cardiogénique,', 'Angor instable,', 'Infarctus du myocarde datant de moins d’un mois.', 'Enfant : l''absence de données cliniques contre-indique l''utilisation de ce produit chez l''enfant.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Il est recommandé d’adapter la posologie chez les personnes âgées, et les insuffisants hépatiques (voir rubrique 4.2).', 'Il est recommandé d’adapter la posologie avec prudence chez les insuffisants rénaux et les insuffisants cardiaques chroniques.', 'Des précautions doivent être prises chez les patients ayant une maladie du nœud sinusal confirmée ou fortement suspectée et qui ne sont pas appareillés avec un pacemaker.', 'Prendre des précautions particulières en cas de faible pression systolique ou de sténose aortique sévère.', 'Une crise angineuse peut survenir principalement chez des patients présentant une cardiopathie ischémique.', 'Lors de l’initiation du traitement ou lors de l’augmentation trop rapide de la posologie chez ces patients, la fréquence, la durée et la sévérité des crises angineuses peuvent se majorer.', 'ICAZ LP 2,5 mg, gélule doit être arrêté en cas de réaction d’hypersensibilité à ce médicament.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations déconseillées', 'Dantrolène', 'Avec le dantrolène administré par perfusion : chez l''animal, des cas de fibrillations ventriculaires mortelles sont constamment observés lors de l''administration de vérapamil et de dantrolène IV.', 'L''association d''un antagoniste du calcium et de dantrolène est donc potentiellement dangereuse.', 'Cependant, quelques patients ont reçu l''association nifédipine et dantrolène sans inconvénient.', 'Associations faisant l''objet de précautions d’emploi', 'Itraconazole, kétoconazole', 'Risque majoré d''effets indésirables, notamment d’œdèmes, par diminution du métabolisme hépatique de la dihydropyridine.', 'Surveillance clinique et adaptation éventuelle de la posologie de la dihydropyridine pendant le traitement par l’itraconazole ou le kétoconazole et après leur arrêt.', 'Anticonvulsivants inducteurs enzymatiques (carbamazepine, fosphenytoine, phénobarbital, phenytoine, primidone, etc.)', 'Diminution des concentrations plasmatiques de l''antagoniste du calcium par augmentation de son métabolisme hépatique par l’inducteur.', 'Surveillance clinique et adaptation éventuelle de la posologie de l''antagoniste du calcium pendant le traitement par l''inducteur et après son arrêt.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquentes : céphalées', 'Fréquentes : sensations vertigineuses', 'Fréquentes : tachycardie, palpitations']);

  -- amlodipine (CIS 69622809)
  m := pg_temp.jp_matrice_by_norm('amlodipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteurs calciques sélectifs à principalement effet vasculaire, code ATC : C08CA01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension.', 'Angor chronique stable.', 'Angor vasospastique (syndrome de Prinzmetal).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['L’amlodipine est contre-indiquée chez les patients présentant :', 'une hypersensibilité à l’amlodipine, aux dérivés de la dihydropyridine ou à l’un des excipients mentionnés à la rubrique 6.1 ;', 'une hypotension sévère ;', 'un choc (y compris choc cardiogénique) ;', 'une obstruction de la voie d’éjection du ventricule gauche (par exemple, sténose aortique de degré élevé) ;', 'une insuffisance cardiaque hémodynamiquement instable après un infarctus aigu du myocarde.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['La sécurité d’emploi et l’efficacité de l’amlodipine au cours d’une crise hypertensive n’ont pas été établies.', 'Patients atteints d’insuffisance cardiaque', 'Les patients atteints d’insuffisance cardiaque doivent être traités avec précaution.', 'Patients atteints d’insuffisance hépatique', 'La demi-vie de l’amlodipine est augmentée et son ASC (Aire Sous la Courbe) est plus grande chez les patients atteints d’insuffisance hépatique ; les recommandations posologiques n’ont pas été établies.', 'Par conséquent l’amlodipine devra être initiée à la dose efficace la plus faible et avec précaution, aussi bien durant l’initiation du traitement que lors de l’augmentation de la dose.', 'Une augmentation posologique lente et une surveillance attentive peuvent être nécessaires chez les patients avec une insuffisance hépatique sévère.', 'Patients âgés', 'Chez les sujets âgés, une augmentation de la posologie doit être effectuée avec précaution (voir rubriques 4.2 et 5.2).', 'Patients atteints d’insuffisance rénale', 'L’amlodipine peut être utilisée chez ces patients à des doses normales.', 'Les changements des concentrations plasmatiques d’amlodipine ne sont pas corrélés avec le degré d’insuffisance rénale.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Effets des autres médicaments sur l’amlodipine', '+ Inhibiteurs du CYP3A4', 'La traduction clinique de ces variations pharmacocinétiques peut être plus prononcée chez le sujet âgé.', 'Par conséquent, une surveillance clinique et un ajustement de la dose pourront être nécessaires.', '+ Inducteurs du CYP3A4', 'Lors de la co-administration d’inducteurs connus du CYP3A4, la concentration plasmatique d’amlodipine peut varier.', '+ Dantrolène (perfusion)', 'Chez l’animal, une fibrillation ventriculaire et un collapsus cardiovasculaire létaux ont été observés en association avec une hyperkaliémie après l’administration de vérapamil et de dantrolène IV.', 'Effets de l’amlodipine sur d’autres médicaments', 'Les effets hypotenseurs de l’amlodipine s’ajoutent à ceux d’autres médicaments présentant des propriétés antihypertensives.', '+ Tacrolimus', '+ Inhibiteurs de la cible mécanique de la rapamycine (mTOR)']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Leucocytopénie, thrombocytopénie']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Une augmentation posologique lente et une surveillance attentive peuvent être nécessaires chez les patients avec une insuffisance hépatique sévère.']);

  -- felodipine (CIS 69451322)
  m := pg_temp.jp_matrice_by_norm('felodipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteur calcique, dérivés de la dihydropyridine, code ATC : C08CA02.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle,', 'Angor stable.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Grossesse,', 'Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1,', 'Insuffisance cardiaque décompensée,', 'Infarctus du myocarde aigu,', 'Angor instable,', 'Sténose valvulaire cardiaque hémodynamiquement significative,', 'Obstruction des voies d’éjection cardiaque.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['L’efficacité et la sécurité d’emploi de la félodipine dans le traitement des urgences hypertensives n’ont pas été étudiées.', 'La félodipine peut entraîner une hypotension significative suivie d''une tachycardie.', 'Cela peut conduire à une ischémie myocardique chez les patients prédisposés.', 'La félodipine est éliminée par le foie.', 'Par conséquent, des concentrations thérapeutiques et une réponse plus importantes peuvent être attendues chez les patients avec une altération de la fonction hépatique (voir rubrique 4.2).', 'L’administration concomitante de médicaments qui induisent ou inhibent fortement les enzymes du CYP3A4 résulte respectivement en la forte diminution ou augmentation des concentrations plasmatiques de félodipine.', 'Par conséquent, de telles associations doivent donc être évitées (voir rubrique 4.5).', 'Ce médicament contient du lactose.', 'Les patients présentant une intolérance au galactose, un déficit total en lactase ou un syndrome de malabsorption du glucose et du galactose (maladies héréditaires rares) ne doivent pas prendre ce médicament.', 'Ce médicament contient moins de 1 mmol (23 mg) de sodium par comprimé, c’est-à-dire qu’il est essentiellement « sans sodium ».', 'Une légère hypertrophie gingivale a été observée chez des patients atteints d''une gingivite/parodontite prononcée.', 'L’hypertrophie peut être évitée ou disparaître avec une hygiène dentaire soignée.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['La félodipine est métabolisée dans le foie par le cytochrome P450 3A4 (CYP3A4).', 'L''administration concomitante de substances qui interfèrent avec le système enzymatique CYP3A4 peut affecter les concentrations plasmatiques de félodipine.', 'Interactions enzymatiques', 'Les substances inhibitrices enzymatiques et inductrices enzymatiques de l''isoenzyme 3A4 du cytochrome P450 peuvent exercer une influence sur la concentration plasmatique de félodipine.', 'Interactions entraînant une augmentation de la concentration plasmatique de félodipine', 'Il a été montré que les inhibiteurs enzymatiques du CYP3A4 entraînent une augmentation des concentrations plasmatiques de félodipine.', 'La Cmax et l''ASC de la félodipine ont augmenté respectivement de 8 fois et de 6 fois lorsque la félodipine a été co-administrée avec de l’itraconazole, un inhibiteur puissant du CYP3A4.', 'Lorsque la félodipine et l''érythromycine ont été co-administrées, la Cmax et l''ASC de la félodipine ont augmenté d''environ 2,5 fois.', 'La cimétidine a augmenté la Cmax et l''ASC de la félodipine d''environ 55 %.', 'L’association avec des inhibiteurs puissants du CYP3A4 doit être évitée.', 'Exemples :', 'Cimétidine,']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent ≥ 1/10']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Par conséquent, des concentrations thérapeutiques et une réponse plus importantes peuvent être attendues chez les patients avec une altération de la fonction hépatique (voir rubrique 4.2).']);

  -- manidipine (CIS 67302931)
  m := pg_temp.jp_matrice_by_norm('manidipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteurs calciques sélectifs à effets vasculaires prédominants, code ATC : C08CA11.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle essentielle légère à modérée.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active, à tout autre produit de la famille des dihydropyridines ou à l''un des excipients mentionnés à la rubrique 6.1.', 'Chez l''enfant.', 'Angor instable ou infarctus du myocarde récent (au cours des 4 premières semaines après l''infarctus).', 'Insuffisance cardiaque non traitée.', 'Insuffisance rénale sévère (clairance de la créatinine', 'Insuffisance hépatique modérée à sévère.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Le produit doit être administré avec prudence chez les patients atteints d''insuffisance hépatique légère, car son effet antihypertenseur peut être majoré chez ce type de patients (voir rubrique 4.2).', 'En raison du ralentissement des processus métaboliques, un ajustement de la posologie est nécessaire chez les sujets âgés (voir rubrique 4.2).', 'En l''absence de données cliniques chez des patients atteints de coronaropathie stable, la prudence est requise chez ce type de patients en raison d''une éventuelle majoration du risque coronarien (voir rubrique 4.8).', 'Dialyse péritonéale', 'La manidipine a été associée au développement d’un effluent péritonéal trouble chez des patients sous dialyse péritonéale.', 'La turbidité est due à une augmentation de la concentration en triglycérides dans l’effluent péritonéal et tend à se résorber après l’arrêt du traitement par manidipine.', 'Excipient', 'MANIDIPINE ARROW contient du lactose monohydraté.', 'Les patients présentant une intolérance au galactose, un déficit total en lactase ou un syndrome de malabsorption du glucose et du galactose (maladies héréditaires rares) ne doivent pas prendre ce médicament.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['L''effet antihypertenseur de la manidipine peut être majoré par l''administration concomitante de diurétiques, de bêtabloquants et, en règle générale, de tout autre antihypertenseur.', 'Les études in vitro montrent que le potentiel d''inhibition du cytochrome P450 par la manidipine ne semble pas cliniquement significatif.', 'Comme pour les autres antagonistes calciques de la famille des dihydropyridines, l''isoenzyme P4503A4 joue vraisemblablement un rôle de catalyseur dans le métabolisme de la manidipine.', 'De plus, l''administration simultanée d''un antagoniste calcique et de digoxine peut entraîner une augmentation des concentrations du glucoside.', 'Alcool : comme avec tous les antihypertenseurs vasodilatateurs, la prudence est de rigueur en cas de consommation concomitante d''alcool, qui est susceptible de potentialiser leurs effets.', 'En conséquence, MANIDIPINE ARROW et le jus de pamplemousse ne devront pas être pris simultanément.', 'Aucune interaction n''a été observée avec les hypoglycémiants oraux.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables les plus fréquents (≥ 1 % et Ils sont dose-dépendants et disparaissent, le plus souvent, spontanément lors de la poursuite du traitement.', 'Très fréquent ≥ 1/10', 'Fréquent ≥ 1/100 et Peu fréquent ≥ 1/1 000 et Rare ≥ 1/10 000 et Très rare Fréquence indéterminée : ne peut être estimée sur la base des données disponibles.', 'Fréquent', 'Peu fréquent']);

  -- lercanidipine (CIS 60171874)
  m := pg_temp.jp_matrice_by_norm('lercanidipine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Inhibiteur calcique sélectif à effets vasculaires prédominants - Dérivés de la dihydropyridine, code ATC : C08CA13.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['LERCANIDIPINE ACCORD est indiqué dans le traitement de l''hypertension essentielle légère à modérée.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Obstacle à l’éjection du ventricule gauche.', 'Insuffisance cardiaque congestive non traitée.', 'Angor instable ou infarctus du myocarde datant de moins d’un mois.', 'Insuffisance hépatique sévère.', 'Insuffisance rénale sévère (DFG', 'En association avec :', 'o inhibiteurs puissants du CYP3A4 (voir rubrique 4.5) ;', 'o ciclosporine (voir rubrique 4.5) ;', 'o pamplemousse ou jus de pamplemousse (voir rubrique 4.5).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Maladie sinusale', 'La lercanidipine doit être administrée avec prudence chez les patients présentant une dysfonction du nœud sinusal (lorsqu’un stimulateur cardiaque n’a pas été installé).', 'Dysfonction ventriculaire gauche', 'Même si des études hémodynamiques contrôlées n’ont révélé aucune altération de la fonction ventriculaire, des précautions doivent être prises chez des patients ayant une dysfonction ventriculaire gauche.', 'Cardiopathie ischémique', 'Les données suggèrent que les patients atteints de cardiopathie ischémique présentent un risque cardiovasculaire élevé sous traitement par certaines dihydropyridines à courte durée d’action.', 'Bien que la lercanidipine possède une longue durée d’action, la prudence est recommandée chez ces patients.', 'Dans de rares cas, certaines dihydropyridines peuvent entraîner des douleurs précordiales ou un angor.', 'Dans de très rares cas, des patients ayant un angor préexistant peuvent présenter une augmentation de la fréquence, de la durée ou de la gravité des crises angineuses.', 'Des cas isolés d’infarctus du myocarde peuvent être observés (voir rubrique 4.8).', 'Utilisation en cas d''insuffisance rénale ou hépatique', 'Une prudence particulière doit être exercée au début du traitement chez les patients présentant une insuffisance rénale légère à modérée.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations contre-indiquées', 'Inhibiteurs du cytochrome CYP3A4', 'La lercanidipine est métabolisée par l’enzyme CYP3A4 et, par conséquent, les inhibiteurs du cytochrome CYP3A4 administrés simultanément peuvent interagir avec le métabolisme et l’élimination de la lercanidipine.', 'L’administration de lercanidipine avec des inhibiteurs du CYP3A4 (par exemple kétoconazole, itraconazole, ritonavir, érythromycine, troléandomycine, clarithromycine) doit être évitée (voir rubrique 4.3).', 'Ciclosporine', 'Une élévation des concentrations plasmatiques de lercanidipine et de ciclosporine a été observée après administration concomitante des 2 principes actifs.', 'Cependant, l''administration concomitante de lercanidipine et de ciclosporine a provoqué une augmentation de 3 fois les concentrations plasmatiques de lercanidipine et une augmentation de 21% de l''ASC de la ciclosporine.', 'La ciclosporine et la lercanidipine ne doivent pas être administrées ensemble (voir rubrique 4.3).', 'Jus de pamplemousse ou de pamplemousse', 'La lercanidipine ne doit pas être prise avec du pamplemousse ou du jus de pamplemousse (voir rubrique 4.3).', 'Associations déconseillées', 'Inducteurs du cytochrome CYP3A4']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Fréquent', 'Peu fréquent']);

  -- verapamil (CIS 60628554)
  m := pg_temp.jp_matrice_by_norm('verapamil');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Inhibiteur calcique sélectif à effets cardiaques directs, code ATC : C08DA01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle ;', 'traitement de l''angor stable.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament NE DOIT JAMAIS ETRE UTILISE en cas de :', 'hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1 ;', 'blocs auriculo-ventriculaires du 2ème et du 3ème degré non appareillés ;', 'choc cardiogénique ;', 'hypotension artérielle (systolique inférieure à 90 mm Hg) ;', 'dysfonctions sinusales ;', 'fibrillation/flutter auriculaire en présence d’une voie de conduction supplémentaire (par exemple associé à un syndrome de Wolff-Parkinson-White).', 'Ces patients ont un risque de développer une tachyarythmie ventriculaire incluant une fibrillation ventriculaire en cas d’administration de chlorhydrate de vérapamil ;', 'enfant, en l''absence de travaux cliniques effectués sur cette catégorie de sujets ;', 'en association avec le dantrolène (voie injectable), l''aliskiren, le millepertuis, le pimozide et l’ivabradine (voir rubrique 4.5).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Infarctus du myocarde aigu', 'Utiliser ce médicament avec précaution en cas d’infarctus du myocarde aigu avec complications (bradycardie, hypotension marquée ou insuffisance ventriculaire gauche).', 'Insuffisance cardiaque', 'Dans le cas où un digitalique est prescrit, il est nécessaire :', 'de surveiller étroitement la conduction auriculo-ventriculaire (effets additifs) ;', 'de contrôler les concentrations de digoxine et d''adapter la posologie (car le vérapamil peut augmenter de façon importante les concentrations plasmatiques de digoxine).', 'Troubles de la conduction/Bloc auriculo-ventriculaire du 1er degré/Bradycardie/Asystole', 'Le chlorhydrate de vérapamil déprime les nœuds auriculo-ventriculaires et sinusaux et prolonge le temps de conduction auriculo-ventriculaire.', 'Ces troubles sont plus susceptibles de survenir chez les patients présentant une maladie du sinus (maladie du sinus auriculoventriculaire), qui est plus fréquente chez les patients âgés.', 'Une asystolie chez les patients qui n’ont pas de maladie du sinus est généralement de courte durée (quelques secondes ou moins), avec un retour spontané à un rythme nodal auriculo-ventriculaire ou sinusal normal.', 'Si cela ne se produit pas rapidement, un traitement approprié doit être instauré immédiatement (voir rubrique 4.8).', 'Insuffisance hépatique']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Médicaments anti-arythmiques', 'De nombreux antiarythmiques sont dépresseurs de l''automatisme, de la conduction et de la contractilité cardiaques.', 'L''association d''antiarythmiques de classes différentes peut apporter un effet thérapeutique bénéfique, mais s''avère le plus souvent très délicate, nécessitant une surveillance clinique étroite et un contrôle de l''ECG.', 'L''association d''antiarythmiques donnant des torsades de pointes (amiodarone, disopyramide, quinidiniques, sotalol) est contre-indiquée.', 'L''association d''antiarythmiques de même classe est déconseillée, sauf cas exceptionnel, en raison du risque accru d''effets indésirables cardiaques.', 'Médicaments bradycardisants', 'De nombreux médicaments peuvent entraîner une bradycardie.', 'Des études in vitro sur le métabolisme ont montré que le chlorhydrate de vérapamil est métabolisé par les cytochromes P450 CYP3A4, CYP1A2, CYP2C8, CYP2C9 et CYP2C18.', 'Il a été montré que le vérapamil est un inhibiteur des enzymes du CYP3A4 et de la glycoprotéine P (P-gp).', 'Par conséquent, les patients doivent être surveillés en ce qui concerne les interactions médicamenteuses.', 'Associations contre-indiquées', '+ Dantrolène (voie injectable) (par mesure de prudence)']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les fréquences sont définies ainsi : très fréquent (≥1/10) ; fréquent (≥1/100, d’après les données disponibles).', 'Fréquents', 'Peu fréquents']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['de surveiller étroitement la conduction auriculo-ventriculaire (effets additifs) ;', 'de contrôler les concentrations de digoxine et d''adapter la posologie (car le vérapamil peut augmenter de façon importante les concentrations plasmatiques de digoxine).']);

  -- diltiazem (CIS 67981763)
  m := pg_temp.jp_matrice_by_norm('diltiazem');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : antagoniste calcique sélectif à effets cardiaques directs/dérivé de benzothiazépine, code ATC : C08DB01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement préventif des crises d''angor stable.', 'Hypertension artérielle.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament NE DOIT JAMAIS ETRE UTILISE en cas de :', 'hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1 ;', 'dysfonction sinusale ;', 'blocs auriculo-ventriculaires du deuxième et troisième degré non appareillés ;', 'insuffisance ventriculaire gauche avec stase pulmonaire ;', 'bradycardie sévère (inférieure ou égale à 40 battements par min).', 'En association avec (voir rubrique 4.5) :', 'o le dantrolène en perfusion,', 'o le pimozide,', 'o la dihydroergotamine,', 'o l''ergotamine,', 'o la nifédipine,']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Le chlorhydrate de diltiazem EST GENERALEMENT DECONSEILLE dans les cas suivants :', 'En association avec :', 'l''esmolol (en cas d''altération de la fonction ventriculaire gauche) ;', 'les bêta-bloquants utilisés dans l''insuffisance cardiaque (bisoprolol, carvédilol, métoprolol, nébivolol) ;', 'les autres bêta-bloquants ;', 'le fingolimod ;', 'la colchicine.', 'Chez la femme enceinte ou susceptible de l''être (voir rubrique 4.6).', 'En revanche, pas de précaution particulière en cas de bloc de branche isolé.', 'Une surveillance étroite de la fonction rénale est conseillée.', 'Chez les sujets âgés, les patients insuffisants rénaux et les patients insuffisants hépatiques, les concentrations plasmatiques de diltiazem peuvent être augmentées.', 'Le diltiazem est susceptible d''entraîner une chute de tension et une bradycardie importante, notamment chez les sujets âgés.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Médicaments antiarythmiques (amiodarone, cibenzoline, diltiazem, disopyramide, dofétilide, dronédarone, flécaïnide, hydroquinidine, ibutilide, lidocaïne, mexilétine, propafénone, quinidine, sotalol, vérapamil)', 'De nombreux antiarythmiques sont dépresseurs de l''automatisme, de la conduction et de la contractilité cardiaques.', 'L''association d''antiarythmiques de classes différentes peut apporter un effet thérapeutique bénéfique, mais s''avère le plus souvent très délicate, nécessitant une surveillance clinique étroite et un contrôle de l''ECG.', 'L''association d''antiarythmiques donnant des torsades de pointes (amiodarone, disopyramide, quinidiniques, sotalol) est contre-indiquée.', 'L''association d''antiarythmiques de même classe est déconseillée, sauf cas exceptionnel, en raison du risque accru d''effets indésirables cardiaques.', 'Médicaments bradycardisants', 'De nombreux médicaments peuvent entraîner une bradycardie.', 'Associations contre-indiquées', '+ Dantrolène administré par perfusion', 'Chez l''animal, des cas de fibrillations ventriculaires mortelles sont constamment observés lors de l''administration de vérapamil et de dantrolène par voie IV.', 'L''association d''un antagoniste du calcium et de dantrolène est donc potentiellement dangereuse.', 'Cependant quelques patients ont reçu l''association nifédipine et dantrolène sans inconvénient.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Fréquent : blocs auriculo-ventriculaires (pouvant être de 1er, 2ème ou 3ème degré ; possibles blocs de branche), palpitations.', 'Peu fréquent : bradycardie.', 'Fréquence indéterminée : blocs sino-auriculaires, insuffisance cardiaque congestive, arrêt sinusal, arrêt cardiaque (asystole).', 'Fréquent : bouffées vasomotrices.', 'Peu fréquent : hypotension orthostatique.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Une surveillance étroite de la fonction rénale est conseillée.']);

  -- carvedilol (CIS 61639048)
  m := pg_temp.jp_matrice_by_norm('carvedilol');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : alpha et bêta-bloquant, code ATC : C07AG02.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Dans un programme d''études cliniques, chez des patients en insuffisance cardiaque légère à modérée, le carvédilol a permis de réduire la mortalité à 6 mois de 50 %, IC 95 % [33 % - 75 %] (voir rubrique 5.1).', 'Dans l''étude COPERNICUS menée chez des patients en insuffisance cardiaque sévère non décompensée, le carvédilol a permis de réduire la mortalité à 1 an de 35 %, IC 95 % [19 % - 48 %] (voir rubrique 5.1).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament ne doit jamais être prescrit dans les cas suivants :', 'hypersensibilité à la substance active ou à l''un des excipients mentionnés à la rubrique 6.1 ;', 'signes cliniques de dysfonctionnement hépatique ;', 'blocs auriculo-ventriculaires des second et troisième degrés (sauf si un pacemaker permanent est en place) ;', 'bradycardie sévère ;', 'maladie du sinus cardiaque (y compris bloc sino-auriculaire) ;', 'hypotension sévère (pression systolique', 'choc cardiogénique ;', 'asthme sévère, broncho-pneumopathies chroniques obstructives sévères, antécédent de bronchospasme sévère ;', 'antécédent de réaction anaphylactique ;', 'phénomènes de Raynaud et troubles circulatoires périphériques (voir rubrique 4.4) ;', 'association à la cimétidine (voir rubrique 4.5) ;']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'L''état du patient doit être stable depuis au moins 4 semaines avant la première prise de carvédilol pour les patients en insuffisance cardiaque légère, modérée et sévère.', 'La prise de ce médicament est déconseillée avec les antagonistes calciques bépridil, diltiazem et vérapamil, et les antihypertenseurs centraux (voir rubrique 4.5) et au cours de l’allaitement.', 'Précautions d''emploi', 'Modalités de surveillance du traitement :', 'au cours de la première semaine de traitement : pouls, pression artérielle couchée et debout, électrocardiogramme, recherche de signes de décompensation ;', 'à chaque augmentation de dose : pouls, pression artérielle couchée et debout, état clinique, électrocardiogramme si nécessaire.', 'Une fois la dose efficace atteinte, une surveillance régulière de l''insuffisance cardiaque et de l''état hémodynamique doit être effectuée, ainsi qu''un contrôle régulier de la fonction rénale, si nécessaire.', 'Si surviennent sous traitement au long cours :', 'une hypotension : réduire la dose de carvédilol à la posologie immédiatement inférieure, voire arrêter le traitement ;', 'Chez les patients souffrant d''insuffisance cardiaque congestive, une aggravation de la défaillance cardiaque ou une rétention liquidienne est possible pendant l''ajustement progressif de la dose de carvédilol.', 'En cas de survenue de tels symptômes, les diurétiques doivent être augmentés et la dose de carvédilol ne doit pas l''être tant qu''un état clinique stable n''a pas été rétabli.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations contre-indiquées (voir rubrique 4.3)', '+ Cimétidine', 'Augmentation des concentrations du carvédilol pouvant être préjudiciables dans le cas du traitement de l''insuffisance cardiaque par diminution de son métabolisme hépatique par la cimétidine.', 'Utiliser un autre anti-sécrétoire gastrique.', '+ Antiarythmiques de la classe I : cibenzoline, disopyramide, flécaïnide, hydroquinidine méxilétine, propafenone, quinidine (sauf lidocaïne)', 'Effet inotrope négatif avec risque de décompensation cardiaque (synergie des effets).', 'Associations déconseillées (voir rubrique 4.4)', '+ Antagonistes du calcium : diltiazem, vérapamil et bépridil', '+ Antihypertenseurs centraux : clonidine, méthyldopa, guanfacine, moxonidine, rilménidine', 'Diminution centrale du tonus sympathique et effet vasodilatateur des antihypertenseurs centraux, préjudiciables en cas d''insuffisance cardiaque traitée par bêta-bloquant et vasodilatateur.', '+ Fingolimod', 'Potentialisation des effets bradycardisants pouvant avoir des conséquences fatales.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['très fréquent : ≥ 1/10 ;', 'fréquent : ≥ 1/100 et', 'peu fréquent : ≥ 1/1 000 et', 'rare : ≥ 1/10 000 et', 'Fréquent']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Modalités de surveillance du traitement :', 'Une fois la dose efficace atteinte, une surveillance régulière de l''insuffisance cardiaque et de l''état hémodynamique doit être effectuée, ainsi qu''un contrôle régulier de la fonction rénale, si nécessaire.']);

  -- bisoprolol (CIS 61859603)
  m := pg_temp.jp_matrice_by_norm('bisoprolol');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : agents bêta-bloquants, sélectifs');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement de l’hypertension.', 'Traitement de l’angor chronique stable.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Le bisoprolol est contre-indiqué chez les patients souffrant d’insuffisance cardiaque chronique dans les cas suivants :', 'insuffisance cardiaque aiguë, ou pendant les épisodes de décompensation de l’insuffisance cardiaque nécessitant un traitement inotrope intraveineux.', 'choc cardiogénique.', 'blocs auriculo-ventriculaires des 2ème ou 3ème degrés.', 'maladie du sinus.', 'bloc sino-auriculaire.', 'bradycardie symptomatique.', 'hypotension symptomatique.', 'asthme sévère.', 'formes sévères de troubles artériels périphériques occlusifs ou formes sévères du phénomène de Raynaud.', 'phéochromocytome non traité (voir rubrique 4.4).', 'acidose métabolique.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'Concernant uniquement l’insuffisance cardiaque chronique :', 'Le traitement de l’insuffisance cardiaque chronique stable par le bisoprolol doit être initié par une période de titration spécifique (voir rubrique 4.2).', 'Concernant toutes les indications :', 'Précautions d’emploi', 'Concernant uniquement l’hypertension ou l’angor :', 'BISOPROLOL ACCORD HEALTHCARE doit être utilisé avec prudence chez les patients souffrant d’hypertension ou d’angor et présentant également une insuffisance cardiaque.', 'L’initiation du traitement par le bisoprolol nécessite une surveillance régulière.', 'Pour la posologie et le mode d’administration, veuillez-vous reporter à la rubrique 4.2.', 'Aucune donnée n’est actuellement disponible sur le traitement de l’insuffisance cardiaque par le bisoprolol chez les patients présentant les pathologies et états suivants :', 'diabète insulino-dépendant (type I).', 'insuffisance rénale sévère.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations déconseillées', 'Concernant uniquement l’insuffisance cardiaque chronique :', '+ Médicaments antiarythmiques de classe I (par exemple, la quinidine, le disopyramide, la lidocaïne, la phénytoïne, le flécaïnide, la propafénone)', 'L’effet sur le temps de conduction auriculo-ventriculaire peut être potentialisé et l’effet inotrope négatif peut être augmenté.', 'Concernant toutes les indications :', '+ Antagonistes calciques de type vérapamil, ou, et dans une moindre mesure, de type diltiazem', 'Effet négatif sur la contractilité et la conduction auriculo-ventriculaire.', 'L’administration intra-veineuse de vérapamil chez les patients sous bêta-bloquants peut induire une hypotension sévère et un bloc auriculo-ventriculaire.', '+ Médicaments antihypertenseurs à action centrale comme la clonidine et autres (par exemple, la méthyldopa, la moxonidine, la rilménidine)', 'Aggravation de l’insuffisance cardiaque par diminution du tonus central sympathique (diminution de la fréquence et du débit cardiaque, vasodilatation).', 'L’arrêt brutal du traitement, en particulier s’il a lieu avant l’arrêt du bêta-bloquant, peut augmenter le risque d’hypertension rebond.', 'Associations faisant l''objet de précautions d’emploi']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent (≥ 1/10)', 'Fréquent (≥ 1/100, Peu fréquent (≥ 1/1 000, Rare (≥ 1/10 000, Très rare (Fréquence inconnue (ne peut être estimée sur la base des données disponibles)', 'Très fréquent : bradycardie.', 'Fréquent : aggravation de l’insuffisance cardiaque.', 'Peu fréquent : troubles de la conduction auriculo-ventriculaire.', 'Fréquent : vertiges*, céphalées*.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['L’initiation du traitement par le bisoprolol nécessite une surveillance régulière.']);

END
$mig$;
